// Activity data models for transaction tracking

export interface Activity {
    id: string;                      // Unique ID (timestamp + random)
    timestamp: number;                // Unix timestamp
    type: ActivityType;               // Operation type
    status: 'pending' | 'success' | 'failed';
    address: string;                  // User address who initiated

    // Transaction Info
    txHash?: string;                  // Transaction hash
    txRequest?: TransactionRequest;   // Original transaction request
    txResponse?: TransactionResponse; // Full transaction response
    txReceipt?: TransactionReceipt;   // Full transaction receipt (logs, events, gas)

    // Details
    details: ActivityDetails;         // Type-specific details

    // Error Info (if failed)
    error?: ErrorInfo;                // Complete error details

    // Metadata
    chainId?: number;                 // Chain ID (1=mainnet, 11155111=sepolia)
    network?: string;                 // Network name (mainnet/testnet)
    blockNumber?: number;             // Block number where tx was included
    gasUsed?: string;                 // Gas used (from receipt)
    gasPrice?: string;                // Gas price (from tx)
    gasCost?: string;                 // Total cost in ETH
}

export type ActivityType =
    | 'CREATE_LOCKER'
    | 'CREATE_LOCK'
    | 'ADD_TO_LOCK'
    | 'UNLOCK'
    | 'VESTING_UNLOCK'
    | 'CHANGE_OWNER'
    | 'ADD_SIGNER'
    | 'REMOVE_SIGNER'
    | 'BATCH_UPDATE_SIGNERS'
    | 'UPDATE_THRESHOLD'
    | 'RESCUE_TOKEN'
    | 'APPROVE_OPERATION'
    | 'EXECUTE_OPERATION'
    | 'TRANSFER_ETH'
    | 'TRANSFER_TOKEN';

export interface ActivityDetails {
    // Common
    token?: string;
    tokenSymbol?: string;
    amount?: string;
    recipient?: string;

    // Specific
    newOwner?: string;
    signers?: string[];
    signersAdded?: string[];
    signersRemoved?: string[];
    threshold?: number;
    opKey?: string;

    // Events emitted (parsed)
    events?: ParsedEvent[];

    // Raw data
    [key: string]: any;
}

export interface TransactionRequest {
    to?: string;
    from?: string;
    data?: string;
    value?: string;
    gasLimit?: string;
    gasPrice?: string;
    maxFeePerGas?: string;
    maxPriorityFeePerGas?: string;
    nonce?: number;
    chainId?: number;
}

export interface TransactionResponse {
    hash: string;
    to?: string;
    from: string;
    nonce: number;
    gasLimit: string;
    gasPrice?: string;
    data: string;
    value: string;
    chainId: number;
    blockNumber?: number;
    blockHash?: string;
    timestamp?: number;
    confirmations?: number;
    type?: number;
    accessList?: any;
    maxPriorityFeePerGas?: string;
    maxFeePerGas?: string;
}

export interface TransactionReceipt {
    to?: string;
    from: string;
    contractAddress?: string;
    transactionIndex: number;
    gasUsed: string;
    logsBloom: string;
    blockHash: string;
    transactionHash: string;
    logs: Log[];
    blockNumber: number;
    confirmations: number;
    cumulativeGasUsed: string;
    effectiveGasPrice: string;
    status: number;
    type: number;
}

export interface Log {
    blockNumber: number;
    blockHash: string;
    transactionIndex: number;
    removed: boolean;
    address: string;
    data: string;
    topics: string[];
    transactionHash: string;
    logIndex: number;
}

export interface ParsedEvent {
    name: string;
    signature: string;
    args: Record<string, any>;
    logIndex: number;
}

export interface ErrorInfo {
    message: string;                  // Human-readable error message
    code?: string;                    // Error code (e.g., 'CALL_EXCEPTION', 'INSUFFICIENT_FUNDS')
    reason?: string;                  // Decoded reason from contract
    data?: string;                    // Raw error data (e.g., '0x30cd7471')
    method?: string;                  // Method that failed
    transaction?: any;                // Transaction that caused the error
    stack?: string;                   // Stack trace
    shortMessage?: string;            // Short error description
    info?: Record<string, any>;       // Additional error info
    contractError?: {
        selector: string;               // Error selector (e.g., '0x30cd7471')
        name?: string;                  // Decoded error name (e.g., 'NotOwner')
        args?: any[];                   // Error arguments if any
    };
}

export interface ActivityFilters {
    type?: ActivityType;
    status?: 'pending' | 'success' | 'failed';
    address?: string;
    token?: string;
    chainId?: number;
    dateFrom?: number;
    dateTo?: number;
    searchQuery?: string;
    lockId?: number;
}

// Utility function to generate unique activity ID
export function generateActivityId(): string {
    return `${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
}

