import { Injectable } from '@angular/core';
import {
    Activity,
    ActivityFilters,
    ActivityType,
    ErrorInfo,
    TransactionReceipt,
    TransactionResponse
} from '@models/activity.model';


@Injectable({
    providedIn: 'root'
})
export class ActivityService {
    private dbName = 'LockerActivities';
    private storeName = 'activities';
    private version = 1;
    private db: IDBDatabase | null = null;

    constructor() {
        this.initDB();
    }

    /**
     * Initialize IndexedDB
     */
    private async initDB(): Promise<void> {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open(this.dbName, this.version);

            request.onerror = () => reject(request.error);
            request.onsuccess = () => {
                this.db = request.result;
                resolve();
            };

            request.onupgradeneeded = (event: any) => {
                const db = event.target.result;

                // Create object store if it doesn't exist
                if (!db.objectStoreNames.contains(this.storeName)) {
                    const objectStore = db.createObjectStore(this.storeName, { keyPath: 'id' });

                    // Create indexes for efficient querying
                    objectStore.createIndex('timestamp', 'timestamp', { unique: false });
                    objectStore.createIndex('type', 'type', { unique: false });
                    objectStore.createIndex('status', 'status', { unique: false });
                    objectStore.createIndex('address', 'address', { unique: false });
                    objectStore.createIndex('txHash', 'txHash', { unique: false });
                    objectStore.createIndex('blockNumber', 'blockNumber', { unique: false });
                }
            };
        });
    }

    /**
     * Ensure DB is initialized
     */
    private async ensureDB(): Promise<IDBDatabase> {
        if (!this.db) {
            await this.initDB();
        }
        return this.db!;
    }

    /**
     * Add a new activity
     */
    async addActivity(activity: Activity): Promise<void> {
        const db = await this.ensureDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([this.storeName], 'readwrite');
            const store = transaction.objectStore(this.storeName);
            const request = store.add(activity);

            request.onsuccess = () => resolve();
            request.onerror = () => reject(request.error);
        });
    }

    /**
     * Update activity status with transaction details
     */
    async updateActivityStatus(
        id: string,
        status: 'pending' | 'success' | 'failed',
        txHash?: string,
        error?: ErrorInfo,
        additionalData?: {
            txResponse?: TransactionResponse;
            txReceipt?: TransactionReceipt;
            blockNumber?: number;
            gasUsed?: string;
            gasPrice?: string;
            gasCost?: string;
            events?: any[];
        }
    ): Promise<void> {
        const db = await this.ensureDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([this.storeName], 'readwrite');
            const store = transaction.objectStore(this.storeName);
            const getRequest = store.get(id);

            getRequest.onsuccess = () => {
                const activity = getRequest.result as Activity;
                if (activity) {
                    activity.status = status;
                    if (txHash) activity.txHash = txHash;
                    if (error) activity.error = error;
                    if (additionalData) {
                        if (additionalData.txResponse) activity.txResponse = additionalData.txResponse;
                        if (additionalData.txReceipt) activity.txReceipt = additionalData.txReceipt;
                        if (additionalData.blockNumber) activity.blockNumber = additionalData.blockNumber;
                        if (additionalData.gasUsed) activity.gasUsed = additionalData.gasUsed;
                        if (additionalData.gasPrice) activity.gasPrice = additionalData.gasPrice;
                        if (additionalData.gasCost) activity.gasCost = additionalData.gasCost;
                        if (additionalData.events) activity.details.events = additionalData.events;
                    }

                    const updateRequest = store.put(activity);
                    updateRequest.onsuccess = () => resolve();
                    updateRequest.onerror = () => reject(updateRequest.error);
                } else {
                    reject(new Error('Activity not found'));
                }
            };

            getRequest.onerror = () => reject(getRequest.error);
        });
    }

    /**
     * Get activities with filters and pagination
     */
    async getActivities(
        filters?: ActivityFilters,
        limit: number = 50,
        offset: number = 0
    ): Promise<Activity[]> {
        const db = await this.ensureDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([this.storeName], 'readonly');
            const store = transaction.objectStore(this.storeName);
            const index = store.index('timestamp');
            const request = index.openCursor(null, 'prev'); // Newest first

            const results: Activity[] = [];
            let skipped = 0;

            request.onsuccess = (event: any) => {
                const cursor = event.target.result;
                if (cursor && results.length < limit) {
                    const activity = cursor.value as Activity;

                    // Apply filters
                    if (this.matchesFilters(activity, filters)) {
                        if (skipped >= offset) {
                            results.push(activity);
                        } else {
                            skipped++;
                        }
                    }
                    cursor.continue();
                } else {
                    resolve(results);
                }
            };

            request.onerror = () => reject(request.error);
        });
    }

    /**
     * Get activity by ID
     */
    async getActivityById(id: string): Promise<Activity | null> {
        const db = await this.ensureDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([this.storeName], 'readonly');
            const store = transaction.objectStore(this.storeName);
            const request = store.get(id);

            request.onsuccess = () => resolve(request.result || null);
            request.onerror = () => reject(request.error);
        });
    }

    /**
     * Get latest activities (for dashboard)
     */
    async getLatestActivities(limit: number = 5): Promise<Activity[]> {
        return this.getActivities({}, limit, 0);
    }

    /**
     * Get total count of activities
     */
    async getTotalCount(filters?: ActivityFilters): Promise<number> {
        const db = await this.ensureDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([this.storeName], 'readonly');
            const store = transaction.objectStore(this.storeName);
            const request = store.openCursor();

            let count = 0;

            request.onsuccess = (event: any) => {
                const cursor = event.target.result;
                if (cursor) {
                    if (this.matchesFilters(cursor.value, filters)) {
                        count++;
                    }
                    cursor.continue();
                } else {
                    resolve(count);
                }
            };

            request.onerror = () => reject(request.error);
        });
    }

    /**
     * Get activities by type
     */
    async getActivitiesByType(type: ActivityType): Promise<Activity[]> {
        return this.getActivities({ type });
    }

    /**
     * Get activities by date range
     */
    async getActivitiesByDateRange(start: number, end: number): Promise<Activity[]> {
        return this.getActivities({ dateFrom: start, dateTo: end });
    }

    /**
     * Search activities
     */
    async searchActivities(query: string): Promise<Activity[]> {
        return this.getActivities({ searchQuery: query });
    }

    /**
     * Clear all activities
     */
    async clearAll(): Promise<void> {
        const db = await this.ensureDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([this.storeName], 'readwrite');
            const store = transaction.objectStore(this.storeName);
            const request = store.clear();

            request.onsuccess = () => resolve();
            request.onerror = () => reject(request.error);
        });
    }

    /**
     * Export activities as JSON
     */
    async exportActivities(): Promise<string> {
        const activities = await this.getAllActivities();
        return JSON.stringify({
            version: '1.0',
            exportDate: Date.now(),
            activities
        }, null, 2);
    }

    /**
     * Import activities from JSON
     */
    async importActivities(json: string): Promise<void> {
        try {
            const data = JSON.parse(json);
            if (data.activities && Array.isArray(data.activities)) {
                for (const activity of data.activities) {
                    await this.addActivity(activity);
                }
            }
        } catch (e) {
            throw new Error('Invalid JSON format');
        }
    }

    /**
     * Get all activities (no pagination)
     */
    private async getAllActivities(): Promise<Activity[]> {
        const db = await this.ensureDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction([this.storeName], 'readonly');
            const store = transaction.objectStore(this.storeName);
            const request = store.getAll();

            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error);
        });
    }

    /**
     * Check if activity matches filters
     */
    private matchesFilters(activity: Activity, filters?: ActivityFilters): boolean {
        if (!filters) return true;

        if (filters.lockId !== undefined && activity.details?.['lockId'] !== filters.lockId) return false;
        if (filters.type && activity.type !== filters.type) return false;
        if (filters.status && activity.status !== filters.status) return false;
        if (filters.address && activity.address.toLowerCase() !== filters.address.toLowerCase()) return false;
        if (filters.token && activity.details.token?.toLowerCase() !== filters.token.toLowerCase()) return false;
        if (filters.dateFrom && activity.timestamp < filters.dateFrom) return false;
        if (filters.dateTo && activity.timestamp > filters.dateTo) return false;
        if (filters.chainId && activity.chainId !== filters.chainId) return false; // Added chainId filter to matchesFilters

        if (filters.searchQuery) {
            const query = filters.searchQuery.toLowerCase();
            const searchableText = [
                activity.txHash,
                activity.address,
                activity.details.token,
                activity.details.tokenSymbol,
                activity.type
            ].join(' ').toLowerCase();

            if (!searchableText.includes(query)) return false;
        }

        return true;
    }
}
